changeSet.sql:
create or alter function [dbo].[GetCombinedPermissionsForUserByAssetTypeId] 
(
	@id int,
	@userId int
)
returns int
as
begin
	declare @defaultPermissions int,
			@combinedPermissionMask int = 0;
	select	@defaultPermissions = [DefaultPermissions]
	from	AssetType
	where	ID = @id;


	declare @permissions dbo.Ids;

	insert into @permissions
		select		top 1
					[Permissions]
		from		ResponsibilitySummary
		where		AssetTypeId = @id and ResourceID = @userId and [Permissions] <> 0;

	if not exists (select 1 from @permissions) and @defaultPermissions is not null
	begin
		if (@defaultPermissions = 1)
		begin
		 insert into @permissions values(1057);
		end
		else
		begin
		 insert into @permissions values(@defaultPermissions);
		end
	end

	if not exists (select Id from @permissions where Id & 1 = 1)
	begin
		if @defaultPermissions = 1
		begin
			insert into @permissions values(1057)
		end
	end

	set	@combinedPermissionMask = dbo.GetCombinedPermissions(@permissions);

	return @combinedPermissionMask
end
